class Solution {
public:
    vector<string> expand(string s) {
        vector<vector<char>> groups;
        int i = 0, n = s.size();
        while (i < n) {
            if (s[i] == '{') {
                int j = s.find('}', i);
                vector<char> g;
                for (int k = i + 1; k < j; k += 2) {
                    g.push_back(s[k]);
                }
                sort(g.begin(), g.end());
                groups.push_back(g);
                i = j + 1;
            } else {
                groups.push_back({s[i++]});
            }
        }

        vector<string> res;
        string path = "";
        auto dfs = [&](auto& self, int idx) -> void {
            if (idx == (int)groups.size()) {
                res.push_back(path);
                return;
            }
            for (char c : groups[idx]) {
                path.push_back(c);
                self(self, idx + 1);
                path.pop_back();
            }
        };

        dfs(dfs, 0);
        return res;
    }
};

class Solution {
    public String[] expand(String s) {
        List<List<Character>> groups = new ArrayList<>();
        int i = 0, n = s.length();
        while (i < n) {
            if (s.charAt(i) == '{') {
                int j = s.indexOf('}', i);
                List<Character> g = new ArrayList<>();
                for (int k = i + 1; k < j; k += 2) {
                    g.add(s.charAt(k));
                }
                Collections.sort(g);
                groups.add(g);
                i = j + 1;
            } else {
                groups.add(Collections.singletonList(s.charAt(i++)));
            }
        }

        List<String> res = new ArrayList<>();
        StringBuilder path = new StringBuilder();
        dfs(groups, 0, path, res);
        return res.toArray(new String[res.size()]);
    }

    private void dfs(List<List<Character>> groups, int idx, StringBuilder path, List<String> res) {
        if (idx == groups.size()) {
            res.add(path.toString());
            return;
        }
        for (char c : groups.get(idx)) {
            path.append(c);
            dfs(groups, idx + 1, path, res);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

var expand = function(s) {
    const groups = [];
    let i = 0, n = s.length;
    while (i < n) {
        if (s[i] === '{') {
            const j = s.indexOf('}', i);
            const g = s.slice(i + 1, j).split(',').sort();
            groups.push(g);
            i = j + 1;
        } else {
            groups.push([s[i++]]);
        }
    }

    const res = [];
    const dfs = (idx, path) => {
        if (idx === groups.length) {
            res.push(path.join(''));
            return;
        }
        for (const c of groups[idx]) {
            path.push(c);
            dfs(idx + 1, path);
            path.pop();
        }
    };

    dfs(0, []);
    return res;
};
